import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Integer> nums = new ArrayList<>();
        nums.add(1);
        nums.add(5);
        nums.add(3);

        nums.stream().filter(n -> n >= 4).map(n -> {
            System.out.println("加工 " + n);
            return n + 100;
        });

        System.out.println("完事");
    }
}
